    10	/**
    11	 * How one kind of document is issued. The sequence of the text is written here once; each kind only
    12	 * fills in the steps that are its own.
    13	 */
    14	public abstract class DocumentLayout {
    15	
    16	    public final ReservationDocument issue(Reservation reservation, Room room) {
    17	        Guest guest = reservation.guest();
    18	        Price price = reservation.price();
    19	        return new ReservationDocument(
    20	                title(),
    21	                reservation.id(),
    22	                guest.name(),
    23	                guest.identification().cpf(),
    24	                guest.identification().companyCnpj(),
    25	                guest.identification().companyName(),
    26	                guest.identification().passport(),
    27	                guest.identification().country(),
    28	                room.number(),
    29	                room.type(),
    30	                reservation.checkIn(),
    31	                reservation.checkOut(),
    32	                price.nights(),
    33	                price.subtotal(),
    34	                price.discount(),
    35	                price.total(),
    36	                text(reservation, room));
    37	    }
    38	
    39	    private String text(Reservation reservation, Room room) {
    40	        Price price = reservation.price();
    41	        StringBuilder text = new StringBuilder();
    42	        text.append(headline(reservation.id())).append('\n');
    43	        text.append(identification(reservation.guest()));
    44	        text.append(roomLabel()).append(": ").append(room.number()).append(" (").append(room.type()).append(")\n");
    45	        text.append(stay(reservation.checkIn(), reservation.checkOut(), price.nights())).append('\n');
    46	        text.append(subtotalLabel()).append(": ").append(money(price.subtotal())).append('\n');
    47	        if (price.discount().signum() > 0) {
    48	            text.append(discountLabel()).append(": ").append(money(price.discount())).append('\n');
    49	        }
    50	        text.append(totalLabel()).append(": ").append(money(price.total())).append('\n');
    51	        text.append(closing(price.total()));
    52	        return text.toString();
    53	    }
    54	
    55	    protected abstract String title();
    56	
    57	    /** The first line, with the reservation number. */
    58	    protected abstract String headline(long reservationId);
    59	
    60	    /** The line(s) that say who the document is for, each ending in a line break. */
    61	    protected abstract String identification(Guest guest);
    62	
    63	    protected abstract String roomLabel();
    64	
    65	    /** The line with the dates and the number of nights. */
    66	    protected abstract String stay(LocalDate checkIn, LocalDate checkOut, int nights);
    67	
    68	    protected abstract String subtotalLabel();
    69	
    70	    protected abstract String discountLabel();
    71	
    72	    protected abstract String totalLabel();
    73	
    74	    protected abstract String money(BigDecimal amount);
    75	
    76	    /** Lines after the total, each ending in a line break; none by default. */
    77	    protected String closing(BigDecimal total) {
    78	        return "";
    79	    }
    80	}
